begin;
select no_plan();
insert into auth.users(id,email) values(md5('sandbox-result')::uuid,'sandbox-result@example.test');
select set_config('request.jwt.claim.sub',md5('sandbox-result')::text,true);
select set_config('test.order',(public.reserve_sandbox_payment_order((select id from public.organizations where personal_owner_id=auth.uid()),gen_random_uuid(),0,(select id from public.billing_plan_versions where plan_key='pro' and version=1),100,'123','https://stage.qvesta.ru',now(),now()+interval '1 month')->>'id'),true);
create function pg_temp.oid() returns uuid language sql as $$select current_setting('test.order')::uuid$$;
create function pg_temp.record(s text default 'pending',t boolean default true) returns jsonb language sql as $$select public.record_sandbox_payment_result(pg_temp.oid(),md5('provider-payment')::uuid,s,s='succeeded',t,'https://yoomoney.ru/test')$$;
select throws_ok($$select pg_temp.record()$$,'22023','invalid sandbox payment result','нельзя записать оплату до отправки');
select lives_ok($$select public.begin_sandbox_payment_send(pg_temp.oid())$$,'отправка подготовлена');
select throws_ok($$select pg_temp.record('pending',false)$$,'22023','invalid sandbox payment result','боевой результат отклоняется');
select is(pg_temp.record()->>'status','pending','результат сохранён');
select is(pg_temp.record()->>'payment_id',md5('provider-payment')::uuid::text,'повтор сохраняет привязку');
select is(public.begin_sandbox_payment_send(pg_temp.oid())->>'can_send','false','после записи ID новая отправка запрещена');
select is(public.read_sandbox_payment_order(pg_temp.oid())->'order'->>'providerPaymentId',md5('provider-payment')::uuid::text,'ID восстанавливается');
select throws_ok($$select public.record_sandbox_payment_result(pg_temp.oid(),gen_random_uuid(),'pending',false,true,null)$$,'22023','sandbox payment binding conflict','другой ID не заменяет оплату');
select is(pg_temp.record('succeeded')->>'status','succeeded','успешный результат сохранён');
select is(pg_temp.record()->>'status','succeeded','поздний pending не откатывает успех');
select is(pg_temp.record('canceled')->>'requires_review','true','противоречивый финал требует проверки');
select is((select status from public.organization_subscriptions where organization_id=(select organization_id from public.billing_sandbox_orders where id=pg_temp.oid())),'unconfigured','тестовая оплата не выдаёт подписку');
select ok((select relrowsecurity from pg_class where oid='public.billing_sandbox_payment_results'::regclass),'RLS включена');
select ok(not has_function_privilege('authenticated','public.record_sandbox_payment_result(uuid,uuid,text,boolean,boolean,text)','execute'),'клиент не подтверждает оплату');
set local role authenticated;
select throws_ok($$select * from public.billing_sandbox_payment_results$$,'42501',null,'таблица закрыта');
reset role;
select set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
select throws_ok($$select public.read_sandbox_payment_order(pg_temp.oid())$$,'42501','billing management denied','чужой заказ закрыт');
select * from finish();
rollback;
